package aaa;

// A bridge whose target, differing only in its return type, is inherited
// from a superclass, called with invokevirtual as scalac does (Scala's
// StdNames has many).  Sub is assembled by hand (generated by a small
// script; version 49):
//
//   class Sub extends Base implements I {
//     public synthetic bridge Object v() { return this.v(); }   // invokevirtual String v()
//   }
//
// OpenLDK names methods without their return types, so the bridge on Sub
// called itself, forever.
public class inheritedbridge extends ClassLoader
{
    public interface I { Object v(); }
    public static class Base { public String v() { return "base"; } }

    private static final byte[] SUB = new byte[] {
        -54,-2,-70,-66,0,0,0,49,0,20,1,0,23,97,97,97,47,105,110,104,101,114,105,116,101,100,98,114,105,100,103,101,36,83,117,98,7,0,1,1,0,24,97,97,97,47,105,110,104,101,114,105,116,101,100,98,114,105,100,103,101,36,66,97,115,101,7,0,3,1,0,21,97,97,97,47,105,110,104,101,114,105,116,101,100,98,114,105,100,103,101,36,73,7,0,5,1,0,6,60,105,110,105,116,62,1,0,3,40,41,86,12,0,7,0,8,10,0,4,0,9,1,0,1,118,1,0,20,40,41,76,106,97,118,97,47,108,97,110,103,47,83,116,114,105,110,103,59,12,0,11,0,12,10,0,2,0,13,1,0,4,67,111,100,101,1,0,6,60,105,110,105,116,62,1,0,3,40,41,86,1,0,1,118,1,0,20,40,41,76,106,97,118,97,47,108,97,110,103,47,79,98,106,101,99,116,59,0,33,0,2,0,4,0,1,0,6,0,0,0,2,0,1,0,16,0,17,0,1,0,15,0,0,0,17,0,1,0,1,0,0,0,5,42,-73,0,10,-79,0,0,0,0,16,65,0,18,0,19,0,1,0,15,0,0,0,17,0,1,0,1,0,0,0,5,42,-74,0,14,-80,0,0,0,0,0,0
    };

    protected Class<?> findClass(String name) throws ClassNotFoundException
    {
        if (!name.equals("aaa.inheritedbridge$Sub")) throw new ClassNotFoundException(name);
        return defineClass(name, SUB, 0, SUB.length);
    }

    public static void main(String[] args) throws Exception
    {
        Class<?> c = new inheritedbridge().loadClass("aaa.inheritedbridge$Sub");
        Object sub = c.getDeclaredConstructor().newInstance();
        Object result;
        try { result = ((I) sub).v() + " " + ((Base) sub).v(); }
        catch (Throwable t) { result = "threw " + t; }
        System.out.println("base base".equals(result) ? "OK" : "FAIL: " + result);
    }
}
